// src/components/Admin/Analytics.js
import React, { useState } from 'react';
import './Analytics.css';

export default function Analytics({ orders = [], tables = [], chefs = [], checkFilter, filterBlur }) {
  const [timeFilter, setTimeFilter] = useState('Daily');
  const week = ['Mon','Tue','Wed','Thur','Fri','Sat','Sun'];

  // --- DYNAMIC CALCULATIONS ---
  // Calculates all metrics, which will be 0 when INITIAL_ORDERS is []
  const totalRevenue = orders.reduce((acc, o) => {
    const orderTotal = o.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return acc + orderTotal;
  }, 0);
  const totalOrders = orders.length;
  const totalClients = new Set(orders.map(o => o.phone)).size;
  const served = orders.filter(o => o.status === 'done').length;
  const dineIn = orders.filter(o => o.type === 'Dine In').length;
  const takeAway = orders.filter(o => o.type === 'Take Away').length;
  // --- END DYNAMIC CALCULATIONS ---

  const reservedTables = tables.filter(t => t.status === 'Reserved');
  const availableTables = tables.filter(t => t.status === 'Available');

  return (
    <div className="analytics-root">
      {/* Top metrics */}
      <div className="metrics-grid" style={{ filter: checkFilter('Metrics') ? 'none' : filterBlur }}>
        <div className="metric-card">
          <div className="metric-icon bubble">
            <svg viewBox="0 0 24 24" width="20" height="20"><circle cx="12" cy="8" r="4" fill="#0F172A"/><rect x="7" y="13" width="10" height="7" fill="#0F172A"/></svg>
          </div>
          <div className="metric-info">
            <div className="metric-label">TOTAL CHEF</div>
            [cite_start]<div className="metric-value">{String(chefs.length).padStart(2, '0')}</div> {/* Hardcoded to 04 initially [cite: 470] */}
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon bubble">
            <svg viewBox="0 0 24 24" width="20" height="20"><path d="M12 3L2 10h20L12 3z" fill="#0F172A"/><rect x="4" y="10" width="16" height="10" fill="#0F172A"/></svg>
          </div>
          <div className="metric-info">
            <div className="metric-label">TOTAL REVENU</div>
            <div className="metric-value">₹{totalRevenue}</div> {/* Dynamic, starts at 0 */}
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon bubble">
            <svg viewBox="0 0 24 24" width="20" height="20"><rect x="5" y="4" width="14" height="16" rx="1" fill="#0F172A"/></svg>
          </div>
          <div className="metric-info">
            <div className="metric-label">TOTAL ORDERS</div>
            <div className="metric-value">{String(totalOrders).padStart(2, '0')}</div> {/* Dynamic, starts at 00 */}
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon bubble">
            <svg viewBox="0 0 24 24" width="20" height="20"><path d="M12 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10zM2 22c0-5.5 4.5-10 10-10s10 4.5 10 10" fill="#0F172A"/></svg>
          </div>
          <div className="metric-info">
            <div className="metric-label">TOTAL CLIENTS</div>
            <div className="metric-value">{String(totalClients).padStart(2, '0')}</div> {/* Dynamic, starts at 00 */}
          </div>
        </div>
      </div>

      {/* Second row (three panels exactly like PDF) */}
      <div className="triple-grid">
        {/* Order Summary (left) */}
        <div className="panel summary" style={{ filter: checkFilter('Summary') ? 'none' : filterBlur }}>
          <div className="panel-head">
            <h3>Order Summary</h3>
            <select className="time-select" value={timeFilter} onChange={(e)=>setTimeFilter(e.target.value)}>
              <option>Daily</option>
              <option>Weekly</option>
              <option>Monthly</option>
            </select>
          </div>

          <div className="summary-tiles">
            <div className="summary-tile">
              <div className="t-label">Served</div>
              <div className="t-value">{String(served).padStart(2, '0')}</div> {/* Dynamic, starts at 00 */}
            </div>
            <div className="summary-tile">
              <div className="t-label">Dine In</div>
              <div className="t-value">{String(dineIn).padStart(2, '0')}</div> {/* Dynamic, starts at 00 */}
            </div>
            <div className="summary-tile">
              <div className="t-label">Take Away</div>
              <div className="t-value">{String(takeAway).padStart(2, '0')}</div> {/* Dynamic, starts at 00 */}
            </div>
          </div>
        </div>

        {/* Revenue (middle) - using a placeholder bar chart to match PDF aesthetic */}
        <div className="panel revenue" style={{ filter: checkFilter('Revenue') ? 'none' : filterBlur }}>
          <div className="panel-head">
            <h3>Revenue</h3>
            <div className="time-pill">{timeFilter}</div>
          </div>

          <div className="chart-area">
            <div className="chart-bars">
              {week.map((d, i) => (
                <div key={d} className="bar-group">
                  <div className="bar" style={{height: `${Math.random() * 80 + 6}%`}} />
                  <div className="bar-label">{d}</div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Tables (right) */}
        <div className="panel tables" style={{ filter: checkFilter('Tables') ? 'none' : filterBlur }}>
          <div className="panel-head"><h3>Tables</h3></div>
          <div className="tables-grid">
            {tables.slice(0, 28).map((table)=>(
              <div key={table.id} className={`table-tile ${table.status.toLowerCase()}`}>
                <div className="table-label">Table</div>
                <div className="table-num">{String(table.number).padStart(2,'0')}</div>
              </div>
            ))}
          </div>
          <div className="legend">
            [cite_start]<div className="legend-item"><span className="dot reserved"></span>Reserved [cite: 483]</div>
            [cite_start]<div className="legend-item"><span className="dot available"></span>Available [cite: 484]</div>
          </div>
        </div>
      </div>

      {/* Bottom row: Chef table (full width) */}
      <div className="panel chefs" style={{ filter: checkFilter('Chef') ? 'none' : filterBlur }}>
        <div className="panel-head"><h3>Chef Name</h3></div>
        <table className="chef-table">
          <thead>
            <tr><th>Chef Name</th><th>Order Taken</th></tr>
          </thead>
          <tbody>
            {chefs.map(c => (
              <tr key={c.id}>
                <td>{c.name}</td>
                <td>{String(c.orders).padStart(2, '0')}</td> {/* Dynamic, starts at 00 */}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
